// Mock Gemini AI function to generate personalized content
const geminiAI = (preferences) => {
  const { categories, intent, budget, persona } = preferences

  const sections = []

  // Add recommended section based on categories
  if (categories && categories.length > 0) {
    categories.forEach((category) => {
      if (mockProducts[category]) {
        sections.push({
          id: `recommended-${category}`,
          title: `Recommended ${category.charAt(0).toUpperCase() + category.slice(1)}`,
          icon: <ShoppingBag className="h-5 w-5" />,
          products: mockProducts[category].filter((p) => p.price <= budget),
        })
      }
    })
  }

  // Add gift section if intent is gifting
  if (intent === "gifting") {
    sections.push({
      id: "perfect-gifts",
      title: "Perfect Gifts",
      icon: <Gift className="h-5 w-5" />,
      products: mockProducts.gifts,
    })
  }

  // Add budget section
  sections.push({
    id: "budget-picks",
    title: `Top Picks Under ₹${budget}`,
    icon: <Sparkles className="h-5 w-5" />,
    products: Object.values(mockProducts)
      .flat()
      .filter((p) => p.price <= budget)
      .sort(() => 0.5 - Math.random())
      .slice(0, 4),
  })

  // Add trending section
  sections.push({
    id: "trending",
    title: "Recently Trending",
    icon: <TrendingUp className="h-5 w-5" />,
    products: mockProducts.trending,
  })

  // Add personalized tip based on persona
  let tip = ""
  switch (persona) {
    case "Budget Shopper":
      tip = "Look for combo offers to maximize your budget!"
      break
    case "Trend Hunter":
      tip = "New collections drop every Friday. Set a reminder!"
      break
    case "Gifter":
      tip = "Add gift wrapping at checkout for a personal touch."
      break
    case "Convenience Seeker":
      tip = "Filter for items with same-day delivery for urgent needs."
      break
    default:
      tip = "Save items to your wishlist to track price changes."
  }

  return {
    sections,
    persona,
    tip,
  }
}

// Product Carousel Component
const ProductCarousel = ({ products }) => {
  const scrollLeft = () => {
    document.getElementById("carousel").scrollBy({ left: -200, behavior: "smooth" })
  }

  const scrollRight = () => {
    document.getElementById("carousel").scrollBy({ left: 200, behavior: "smooth" })
  }

  return (
    <div className="relative">
      <div
        id="carousel"
        className="flex overflow-x-auto space-x-4 pb-4 scrollbar-hide"
        style={{ scrollbarWidth: "none", msOverflowStyle: "none" }}
      >
        {products.map((product) => (
          <Card key={product.id} className="min-w-[200px] max-w-[200px] flex-shrink-0">
            <CardContent className="p-3">
              <div className="aspect-square rounded-md overflow-hidden mb-3">
                <img
                  src={product.image || "/placeholder.svg"}
                  alt={product.name}
                  className="w-full h-full object-cover transition-transform hover:scale-105"
                />
              </div>
              <h3 className="font-medium line-clamp-1">{product.name}</h3>
              <div className="flex items-center mt-1 text-sm">
                <Star className="h-3 w-3 fill-current text-yellow-500 mr-1" />
                <span>{product.rating}</span>
              </div>
              <div className="flex justify-between items-center mt-2">
                <span className="font-bold">₹{product.price}</span>
                <Button size="sm" variant="outline" className="h-8 w-8 p-0">
                  <ShoppingCart className="h-4 w-4" />
                </Button>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>
      <Button
        variant="outline"
        size="icon"
        className="absolute left-0 top-1/2 -translate-y-1/2 -ml-4 bg-white rounded-full h-8 w-8 shadow-md"
        onClick={scrollLeft}
      >
        <ChevronLeft className="h-4 w-4" />
      </Button>
      <Button
        variant="outline"
        size="icon"
        className="absolute right-0 top-1/2 -translate-y-1/2 -mr-4 bg-white rounded-full h-8 w-8 shadow-md"
        onClick={scrollRight}
      >
        <ChevronRight className="h-4 w-4" />
      </Button>
    </div>
  )
}

